function CoachCommunications({session,category}){const[f,setF]=useState({title:'',body:''}),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),[history,setHistory]=useState([]);const load=()=>fetch('/api/notifications/communications/history',{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.json()).then(d=>setHistory((d.communications||[]).filter(x=>String(x.category)===String(category))));useEffect(()=>{load()},[category]);async function send(){if(busy||!f.title.trim()||!f.body.trim())return;setBusy(true);setMsg('');try{const r=await fetch('/api/notifications/communication',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({competition:'FEFI',category,title:f.title,body:f.body})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'No se pudo enviar.');setMsg('Comunicación enviada'+(d.push?.sent?' · '+d.push.sent+' push':'')+'.');setF({title:'',body:''});load()}catch(e){setMsg(e.message)}finally{setBusy(false)}}return <section className="addPlayer"><small>COMUNICACIONES · {category}</small><h3>Enviar a las familias</h3><label>Título<input value={f.title} onChange={e=>setF({...f,title:e.target.value})} placeholder="Ej. Cambio de horario"/></label><label>Mensaje<textarea rows="4" value={f.body} onChange={e=>setF({...f,body:e.target.value})} placeholder="Escribí el comunicado..."/></label>{msg&&<p className={msg.includes('enviada')?'successMsg':'formError'}>{msg}</p>}<button className="primary wide" disabled={busy||!f.title.trim()||!f.body.trim()} onClick={send}>{busy?'Enviando…':'Enviar comunicación'}</button>{history.length>0&&<div className="childrenAdded communicationHistory"><small>ÚLTIMOS ENVIADOS</small>{history.slice(0,5).map(x=><div className="communicationHistoryItem" key={x.id}><b>{x.title}</b><small>{new Date(x.created_at).toLocaleDateString('es-AR')}</small><small className="readMetric">✓ {x.read_count||0} {(x.read_count||0)===1?'lectura':'lecturas'}</small></div>)}</div>}</section>}
function CoachHome({session}){const logout=()=>{localStorage.removeItem('defe_coach');location.reload()};const[cat,setCat]=useState(session.categories?.[0]||''),[players,setPlayers]=useState([]),[fefiMatch,setFefiMatch]=useState(null),[selected,setSelected]=useState([]),[citation,setCitation]=useState(''),[notes,setNotes]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),[callupState,setCallupState]=useState({players:[],summary:{yes:0,no:0,pending:0}}),[coachTab,setCoachTab]=useState('programacion'),[coachBirthdays,setCoachBirthdays]=useState([]);useEffect(()=>{setCoachBirthdays([]);if(!cat)return;fetch('/api/availability/birthdays?competition=FEFI&category='+encodeURIComponent(cat),{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.ok?r.json():Promise.reject()).then(d=>setCoachBirthdays(d.birthdays||[])).catch(()=>setCoachBirthdays([]))},[cat]);useEffect(()=>{if(!cat)return;fetch('/api/profe/squad?category='+encodeURIComponent(cat),{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.json()).then(d=>{setPlayers(d.players||[]);setSelected((d.players||[]).map(p=>p.id))})},[cat]);useEffect(()=>{if(!cat)return;fetch('/api/profe/next-match?category='+encodeURIComponent(cat),{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.json()).then(d=>{setFefiMatch(d.match||null);setCitation('');setMsg('')})},[cat]);useEffect(()=>{if(!cat||!fefiMatch?.id)return;const load=()=>fetch('/api/profe/callups?match_id='+fefiMatch.id+'&category='+encodeURIComponent(cat),{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.json()).then(d=>setCallupState(d));load();const timer=setInterval(load,15000);return()=>clearInterval(timer)},[cat,fefiMatch?.id]);async function publish(){if(!fefiMatch||!selected.length||busy)return;setBusy(true);setMsg('');try{const r=await fetch('/api/profe/callups',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({match_id:fefiMatch.id,category:cat,person_ids:selected,citation_time:citation||null,notes:notes||null})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'No se pudo publicar la convocatoria.');setMsg('Convocatoria publicada para '+d.players+' jugadores.')}catch(e){setMsg(e.message)}finally{setBusy(false)}}return <main className="coachApp"><header><div className="brand"><img className="clubLogo" src={LOGO}/><div><b>MI DEFE</b><small>PROFESOR</small></div></div><button className="logoutBtn" onClick={logout}>Salir</button></header><nav className="coachTabs coachTopTabs"><button className={coachTab==='programacion'?'active':''} onClick={()=>setCoachTab('programacion')}><CalendarDays className="tabIcon"/><small>Fecha FEFI</small></button><button className={coachTab==='convocatorias'?'active':''} onClick={()=>setCoachTab('convocatorias')}><ClipboardCheck className="tabIcon"/><small>Convocatoria</small></button><button className={coachTab==='plantel'?'active':''} onClick={()=>setCoachTab('plantel')}><Users className="tabIcon"/><small>Plantel</small></button><button className={coachTab==='mensajes'?'active':''} onClick={()=>setCoachTab('mensajes')}><Megaphone className="tabIcon"/><small>Mensajes</small></button><button className={coachTab==='cumples'?'active':''} onClick={()=>setCoachTab('cumples')}><Cake className="tabIcon"/><small>Cumples</small></button></nav><article><div className="coachWelcome"><div><h1>Hola, {(session.user?.first_name||session.user?.email||'Profe').split(' ')[0]}</h1><p className="muted">Plantel asignado</p></div><NotifyButton token={session.token}/></div>{session.categories?.length>1?<select className="coachCategory" value={cat} onChange={e=>setCat(e.target.value)}>{session.categories.map(x=><option key={x}>{x}</option>)}</select>:<p><b>{cat}</b></p>}{coachTab==='programacion'&&<section><small>FEFI · ZONA H</small><h3>Próxima fecha</h3>{fefiMatch?<><div className="programMatch"><div><b>{fefiMatch.home} vs. {fefiMatch.away}</b><small>{fefiMatch.round_name} · {String(fefiMatch.date).slice(0,10)} · {fefiMatch.home_away==='local'?'Local':'Visitante'}</small><small>Cat. {cat} · {fefiMatch.match_time?fefiMatch.match_time+' hs':'Horario a confirmar'}</small>{fefiMatch.venue&&<small>Sede: {fefiMatch.venue}</small>}</div></div><button className="primary wide" onClick={()=>setCoachTab('convocatorias')}>Preparar convocatoria</button></>:<p className="muted">No encontramos una próxima fecha oficial publicada por FEFI.</p>}</section>}{coachTab==='mensajes'&&<CoachCommunications session={session} category={cat}/>} {coachTab==='cumples'&&<section><small>🎂 CUMPLEAÑOS · {cat}</small><h3>Próximos cumpleaños</h3><div className="birthdayList">{coachBirthdays.length?coachBirthdays.map(b=><div className={b.days_until===0?'birthdayRow today':'birthdayRow'} key={b.person_id}><div className="birthdayBadge">{b.days_until===0?'🎉':'🎂'}</div><div><b>{b.name}</b><small>{new Date(2000,b.month-1,b.day).toLocaleDateString('es-AR',{day:'numeric',month:'long'})}</small></div><strong>{b.days_until===0?'HOY':b.days_until===1?'MAÑANA':'en '+b.days_until+' días'}</strong></div>):<p className="muted">No hay fechas de cumpleaños cargadas para esta categoría.</p>}</div></section>} {coachTab==='plantel'&&<section><small>MI PLANTEL</small><h3>{players.length} {players.length===1?'jugador':'jugadores'}</h3><div className="squadList readonly">{players.map(p=><div className="squadPlayer" key={p.id}><span><b>{p.full_name}</b><small>{p.category}</small></span></div>)}</div></section>}{coachTab==='convocatorias'&&<section className="addPlayer"><small>CONVOCATORIA · FEFI</small><h3>{fefiMatch?fefiMatch.round_name:'Próxima fecha'}</h3>{fefiMatch?<><p><b>{fefiMatch.home} vs. {fefiMatch.away}</b></p><p className="muted">{String(fefiMatch.date).slice(0,10)} · Partido {fefiMatch.match_time||'a confirmar'} hs · {fefiMatch.home_away==='local'?'Local':'Visitante'}</p>{callupState.callup?<><div className="matchStatus"><b className="called">CONVOCATORIA ENVIADA</b></div><div className="responseSummary"><span><b>{callupState.summary?.yes||0}</b><small>Confirmados</small></span><span><b>{callupState.summary?.no||0}</b><small>No asisten</small></span><span><b>{callupState.summary?.pending||0}</b><small>Pendientes</small></span></div><div className="existingCallup">{callupState.players.map(x=><span key={x.row_id}><b>{x.full_name}</b> · {x.attendance==='yes'?'✓ Confirmó':x.attendance==='no'?'✕ No asiste':'• Pendiente'}</span>)}</div><button className="secondary wide" onClick={()=>setCallupState({...callupState,callup:null,editing:true})}>Editar convocatoria</button></>:<><label>Hora de citación<input type="time" value={citation} onChange={e=>setCitation(e.target.value)}/></label><label>Indicaciones<textarea rows="3" value={notes} onChange={e=>setNotes(e.target.value)} placeholder="Ej. Llegar con camiseta y pantalón del club"/></label><small>JUGADORES CONVOCADOS</small><div className="squadList">{players.map(p=><label key={p.id}><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>setSelected(selected.includes(p.id)?selected.filter(x=>x!==p.id):[...selected,p.id])}/><span><b>{p.full_name}</b><small>{p.category}</small></span></label>)}</div>{msg&&<p className={msg.includes('publicada')?'successMsg':'formError'}>{msg}</p>}<button className="primary wide" disabled={busy||!selected.length} onClick={publish}>{busy?'Guardando…':callupState.editing?'Guardar cambios':'Enviar convocatoria'} ({selected.length})</button></>}</>:<p className="muted">Todavía no hay una próxima fecha FEFI disponible para esta categoría.</p>}</section>}</article></main>}
function AdminCommunications({session,cats}){const[f,setF]=useState({category:'2013',title:'',body:''}),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false),[history,setHistory]=useState([]);const load=()=>fetch('/api/notifications/communications/history',{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.json()).then(d=>setHistory(d.communications||[]));useEffect(load,[]);async function send(){if(busy)return;setBusy(true);setMsg('');try{const r=await fetch('/api/notifications/communication',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({competition:'FEFI',category:f.category,title:f.title,body:f.body})}),d=await r.json();if(!r.ok)throw new Error(d.detail||d.error||'No se pudo enviar.');const pushed=d.push?.sent||0;setMsg('Comunicación enviada'+(pushed?' · '+pushed+' push enviado'+(pushed===1?'':'s'):'')+'.');setF({...f,title:'',body:''});load()}catch(e){setMsg(e.message)}finally{setBusy(false)}}return <section className="addPlayer"><small>COMUNICACIONES</small><h3>Enviar a familias</h3><label>Plantel<select value={f.category} onChange={e=>setF({...f,category:e.target.value})}><optgroup label="FEFI · Baby Fútbol">{FEFI_CATEGORIES.map(y=><option key={y}>{y}</option>)}</optgroup></select></label><label>Título<input value={f.title} onChange={e=>setF({...f,title:e.target.value})} placeholder="Ej. Cambio de horario"/></label><label>Mensaje<textarea rows="4" value={f.body} onChange={e=>setF({...f,body:e.target.value})} placeholder="Escribí el comunicado..."/></label>{msg&&<p className={msg.includes('enviada')?'successMsg':'formError'}>{msg}</p>}<button className="primary wide" disabled={busy||!f.title.trim()||!f.body.trim()} onClick={send}>{busy?'Enviando…':'Enviar comunicación'}</button>{history.length>0&&<div className="childrenAdded communicationHistory"><small>ÚLTIMOS ENVIADOS</small>{history.slice(0,5).map(x=><div className="communicationHistoryItem" key={x.id}><b>{x.title}</b><small>{x.category} · {new Date(x.created_at).toLocaleDateString('es-AR')}</small><small className="readMetric">✓ {x.read_count||0} {(x.read_count||0)===1?'lectura':'lecturas'}</small></div>)}</div>}</section>}
function AdminHome({session}){const[adminTab,setAdminTab]=useState('inicio'),[showCoachForm,setShowCoachForm]=useState(false);const[responseDetail,setResponseDetail]=useState({});const[coaches,setCoaches]=useState([]);const loadCoaches=async()=>{try{const r=await fetch('/api/admin/users',{headers:{Authorization:'Bearer '+session.token}}),users=await r.json();if(!r.ok)throw new Error(users.detail||'No pudimos cargar profesores.');const profs=(Array.isArray(users)?users:[]).filter(u=>u.role==='profe');const enriched=await Promise.all(profs.map(async u=>{const tr=await fetch('/api/admin/users/'+u.id+'/profe-teams',{headers:{Authorization:'Bearer '+session.token}}),td=await tr.json();return {...u,full_name:[u.first_name,u.last_name].filter(Boolean).join(' ')||u.email,categories:(td.selections||[]).map(x=>x.split('|')[1]).filter(Boolean)}}));setCoaches(enriched)}catch(e){setMsg(e.message)}};useEffect(()=>{loadCoaches()},[]);const logout=()=>{localStorage.removeItem('defe_admin');location.reload()};const[locationOptions,setLocationOptions]=useState([]),[locationBusy,setLocationBusy]=useState(false),[locationPicked,setLocationPicked]=useState(false);const cats=FEFI_CATEGORIES;const[f,setF]=useState({fullName:'',phone:'',email:'',password:'',categories:['2013']}),[msg,setMsg]=useState(''),[matches,setMatches]=useState([]),[p,setP]=useState({category:'2013',opponent:'',matchDate:'',matchTime:'',presentationTime:'',venue:'',location:'',homeAway:'local'}),[editId,setEditId]=useState(null),[pmsg,setPmsg]=useState('');const load=()=>fetch('/api/admin-programming',{headers:{Authorization:'Bearer '+session.token}}).then(r=>r.json()).then(d=>setMatches(d.matches||[]));useEffect(load,[]);useEffect(()=>{if(locationPicked||p.location.trim().length<4){setLocationOptions([]);return}const t=setTimeout(async()=>{setLocationBusy(true);try{const q=encodeURIComponent(p.location.trim());const r=await fetch("/api/location-search?q="+q);const d=await r.json();if(!r.ok)throw new Error(d.error||"Error de búsqueda");setLocationOptions((d.results||[]).map((x,i)=>({id:x.place_id||i,label:x.display_name||"",lat:x.lat,lon:x.lon})).filter(x=>x.label))}catch(e){setLocationOptions([]);setPmsg("No pudimos buscar ubicaciones. Probá nuevamente.")}finally{setLocationBusy(false)}},550);return()=>clearTimeout(t)},[p.location,locationPicked]);async function create(){setMsg('');try{const parts=f.fullName.trim().split(/\s+/),first_name=parts.shift()||'',last_name=parts.join(' ')||'-';if(!first_name||!f.email.trim()||f.password.length<8||!f.categories.length)throw new Error('Completá los datos y elegí al menos una categoría.');const r=await fetch('/api/users',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({email:f.email.trim().toLowerCase(),password:f.password,role:'profe',first_name,last_name,phone:f.phone})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'No pudimos crear el profesor.');const ar=await fetch('/api/admin/users/'+d.id+'/profe-teams',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({selections:f.categories.map(x=>'FEFI|'+x)})}),ad=await ar.json();if(!ar.ok)throw new Error(ad.detail||'Profesor creado, pero no pudimos asignar sus categorías.');setMsg('Profesor creado y habilitado.');setF({fullName:'',phone:'',email:'',password:'',categories:['2013']});await loadCoaches()}catch(e){setMsg(e.message)}}async function saveProgramming(){setPmsg('');const r=await fetch('/api/admin-programming',{method:editId?'PUT':'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({...p,id:editId})}),d=await r.json();setPmsg(r.ok?(editId?'Programación actualizada y reenviada.':'Programación publicada.'):(d.error||'No pudimos guardar.'));if(r.ok){setEditId(null);setP({...p,opponent:'',matchDate:'',matchTime:'',presentationTime:'',venue:'',location:''});load()}}function editMatch(m){setEditId(m.id);setP({category:m.category,opponent:m.opponent,matchDate:String(m.match_date).slice(0,10),matchTime:String(m.match_time).slice(0,5),presentationTime:m.presentation_time?String(m.presentation_time).slice(0,5):'',venue:m.venue||'',location:m.location||'',homeAway:m.home_away||'local'});window.scrollTo({top:0,behavior:'smooth'})}return <main className="adminApp"><header><div className="brand"><img className="clubLogo" src={LOGO}/><div><b>MI DEFE</b><small>ADMINISTRACIÓN</small></div></div><button className="logoutBtn" onClick={logout}>Salir</button></header><nav className="adminTabs"><button className={adminTab==='inicio'?'active':''} onClick={()=>setAdminTab('inicio')}><LayoutDashboard className="tabIcon"/><small>Inicio</small></button><button className={adminTab==='comunicaciones'?'active':''} onClick={()=>setAdminTab('comunicaciones')}><Megaphone className="tabIcon"/><small>Comunicaciones</small></button><button className={adminTab==='profesores'?'active':''} onClick={()=>setAdminTab('profesores')}><Users className="tabIcon"/><small>Profesores</small></button></nav><article>
{adminTab==='inicio'&&<><div className="adminWelcome"><div><h1>Hola, {(session.user?.first_name||session.user?.email||'Admin').split(' ')[0]}</h1><p>Gestión de profesores, comunicaciones y seguimiento FEFI.</p></div><NotifyButton token={session.token}/></div><section className="adminOverview adminOverviewHome"><small>FEFI · ZONA H</small><h3>Estado general</h3><div className="overviewGrid"><div><b>FEFI</b><span>Fuente deportiva oficial</span></div><div><b>{matches.filter(m=>Number(m.called_up)>0).length}</b><span>Convocatorias enviadas</span></div><div><b>{matches.reduce((n,m)=>n+Number(m.confirmed||0),0)}</b><span>Asistencias confirmadas</span></div><div><b>{matches.reduce((n,m)=>n+Number(m.pending||0),0)}</b><span>Respuestas pendientes</span></div></div></section><section><div className="sectionTitleRow"><div><small>FEFI · ZONA H</small><h3>Seguimiento</h3></div></div>{matches.length?matches.slice(0,2).map(m=><div className="adminMatch adminTracking" key={m.id}><div className="adminMatchMain"><div><b>{m.category} · {m.opponent}</b><small>{String(m.match_date).slice(0,10)} · {String(m.match_time).slice(0,5)} hs · {m.home_away==='local'?'Local':'Visitante'}</small></div></div><div className="adminFlow"><span className="flowDone">✓ Programación</span><span className={Number(m.called_up)>0?'flowDone':'flowPending'}>{Number(m.called_up)>0?'✓ Convocatoria':'• Convocatoria pendiente'}</span></div>{Number(m.called_up)>0&&<><div className="responseProgress"><div style={{width:(Number(m.called_up)?Math.round((Number(m.responded||0)/Number(m.called_up))*100):0)+'%'}}></div></div><small className="responseProgressText">{m.responded||0} de {m.called_up} respondieron</small></>}</div>):<p className="muted">Todavía no hay programaciones futuras.</p>}</section><section className="quickActions"><small>ACCESOS RÁPIDOS</small><div><button onClick={()=>setAdminTab('comunicaciones')}><b>◉ Enviar comunicación</b><span>Informá a las familias</span></button><button onClick={()=>setAdminTab('profesores')}><b>♟ Gestionar profesores</b><span>Alta y asignación de planteles</span></button></div></section></>}
{adminTab==='partidos'&&<><div className="tabHeading"><h1>Partidos</h1><p>Programación y seguimiento de convocatorias.</p></div><section className="addPlayer"><small>PROGRAMACIÓN</small><h3>{editId?'Editar programación':'Publicar partido'}</h3><label>Plantel<select value={p.category} onChange={e=>setP({...p,category:e.target.value})}>{cats.map(x=><option key={x}>{x}</option>)}</select></label><label>Rival<input value={p.opponent} onChange={e=>setP({...p,opponent:e.target.value})}/></label><div className="formPair"><label>Fecha<input type="date" value={p.matchDate} onChange={e=>setP({...p,matchDate:e.target.value})}/></label><label>Hora<input type="time" value={p.matchTime} onChange={e=>setP({...p,matchTime:e.target.value})}/></label></div><label>Hora de presentación (opcional)<input type="time" value={p.presentationTime} onChange={e=>setP({...p,presentationTime:e.target.value})}/></label><label>Condición<select value={p.homeAway} onChange={e=>setP({...p,homeAway:e.target.value})}><option value="local">Local</option><option value="visitante">Visitante</option></select></label><label className="locationField">Ubicación<input placeholder="Escribí club, cancha o dirección..." value={p.location} onChange={e=>{setLocationPicked(false);setP({...p,location:e.target.value})}}/>{locationBusy&&<small className="locationHint">Buscando ubicaciones…</small>}{locationOptions.length>0&&<div className="locationOptions">{locationOptions.map(x=><button type="button" key={x.id} onClick={()=>{setP({...p,location:x.label});setLocationPicked(true);setLocationOptions([])}}><b>{x.label.split(",")[0]}</b><small>{x.label}</small></button>)}</div>}<small className="mapAttribution">Datos © OpenStreetMap contributors</small></label>{pmsg&&<p className={pmsg.includes('publicada')||pmsg.includes('actualizada')?'successMsg':'formError'}>{pmsg}</p>}<button className="primary wide" onClick={saveProgramming}>{editId?'Guardar cambios':'Publicar programación'}</button>{editId&&<button className="forgot" onClick={()=>setEditId(null)}>Cancelar edición</button>}</section><section><small>PRÓXIMAS PROGRAMACIONES</small>{matches.length?matches.map(m=><div className="adminMatch adminTracking" key={m.id}><div className="adminMatchMain"><div><b>{m.category} · {m.opponent}</b><small>{String(m.match_date).slice(0,10)} · {String(m.match_time).slice(0,5)} hs · {m.home_away==='local'?'Local':'Visitante'}</small></div><div className="adminMatchActions"><button onClick={()=>editMatch(m)}>Editar</button><button className="deleteMatch" onClick={async()=>{if(!confirm('¿Eliminar esta programación? También se eliminará su convocatoria.'))return;const r=await fetch('/api/admin-programming?id='+m.id,{method:'DELETE',headers:{Authorization:'Bearer '+session.token}});if(r.ok){if(editId===m.id)setEditId(null);load()}}}>Eliminar</button></div></div><div className="adminFlow"><span className="flowDone">✓ Programación publicada</span><span className={Number(m.called_up)>0?'flowDone':'flowPending'}>{Number(m.called_up)>0?'✓ Convocatoria enviada':'• Convocatoria pendiente'}</span></div>{Number(m.called_up)>0&&<><div className="responseSummary compact adminCounts"><span>✓ {m.confirmed} {Number(m.confirmed)===1?'confirmado':'confirmados'}</span><span>× {m.declined} no asisten</span><span>· {m.pending} pendientes</span></div><div className="responseProgress"><div style={{width:(Number(m.called_up)?Math.round((Number(m.responded||0)/Number(m.called_up))*100):0)+'%'}}></div></div><small className="responseProgressText">{m.responded||0} de {m.called_up} respondieron · {Number(m.called_up)?Math.round((Number(m.responded||0)/Number(m.called_up))*100):0}%</small><button className="viewResponses" onClick={async()=>{if(responseDetail[m.id]){setResponseDetail({...responseDetail,[m.id]:null});return}const r=await fetch('/api/admin-programming?detail='+m.id,{headers:{Authorization:'Bearer '+session.token}}),d=await r.json();setResponseDetail({...responseDetail,[m.id]:d.players||[]})}}>Ver respuestas</button>{responseDetail[m.id]&&<div className="adminResponseList">{responseDetail[m.id].map(x=><div key={x.id}><b>{x.full_name}</b><span className={'responseStatus '+x.status}>{x.status==='yes'?'✓ Asiste':x.status==='no'?'✕ No asiste':'• Pendiente'}</span></div>)}</div>}</>}</div>):<p className="muted">Todavía no hay programaciones futuras.</p>}</section></>}
{adminTab==='comunicaciones'&&<><div className="tabHeading"><h1>Comunicaciones</h1><p>Mensajes para las familias por plantel o para todo el club.</p></div><AdminCommunications session={session} cats={cats}/></>}
{adminTab==='profesores'&&<><div className="tabHeading"><h1>Profesores</h1><p>Usuarios y asignación de planteles.</p></div><section className="addPlayer"><div className="sectionTitleRow"><div><small>PROFESORES REGISTRADOS</small><h3>{coaches.length} {coaches.length===1?'profesor':'profesores'}</h3></div><button className="addMini" onClick={()=>setShowCoachForm(!showCoachForm)}>{showCoachForm?'Cerrar':'+ Nuevo profesor'}</button></div>{showCoachForm&&<div className="coachCreateForm"><label>Nombre y apellido<input value={f.fullName} onChange={e=>setF({...f,fullName:e.target.value})}/></label><label>Celular<input value={f.phone} onChange={e=>setF({...f,phone:e.target.value})}/></label><label>Email<input value={f.email} onChange={e=>setF({...f,email:e.target.value})}/></label><label>Contraseña inicial<input type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})}/></label><label>Plantel<select value={f.category} onChange={e=>setF({...f,category:e.target.value})}><optgroup label="FEFI · Baby Fútbol">{FEFI_CATEGORIES.map(y=><option key={y}>{y}</option>)}</optgroup></select></label>{msg&&<p className={msg.includes('habilitado')?'successMsg':'formError'}>{msg}</p>}<button className="primary wide" onClick={create}>Crear profesor</button></div>}<div className="coachAdminList">{coaches.map(c=><div key={c.id}><span><b>{c.full_name}</b><small>{c.email}</small><div className="categoryChecks compact">{cats.map(x=><label key={x} className={(c.categories||[]).includes(x)?'categoryCheck selected':'categoryCheck'}><input type="checkbox" checked={(c.categories||[]).includes(x)} onChange={async()=>{const next=(c.categories||[]).includes(x)?(c.categories||[]).filter(y=>y!==x):[...(c.categories||[]),x];if(!next.length){setMsg('El profesor debe tener al menos una categoría.');return}const r=await fetch('/api/admin/users/'+c.id+'/profe-teams',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+session.token},body:JSON.stringify({selections:next.map(y=>'FEFI|'+y)})});if(r.ok)loadCoaches()}}/><span>{x}</span></label>)}</div></span><span className={c.is_active?'coachActive':'coachInactive'}>{c.is_active?'Activo':'Inactivo'}</span></div>)}</div></section></>}
</article></main>}
function Register({done}){const[type,setType]=useState('familia'),[loginType,setLoginType]=useState('familia'),[mode,setMode]=useState(null),[form,setForm]=useState({fullName:'',phone:'',email:'',password:'',playerName:'',birthDate:'',category:'2013'}),[children,setChildren]=useState([]),[error,setError]=useState(''),[busy,setBusy]=useState(false),[login,setLogin]=useState({identifier:'',password:''}),[reset,setReset]=useState(false),[newPassword,setNewPassword]=useState(''),[coachLogin,setCoachLogin]=useState({identifier:'',password:''}),[coachReset,setCoachReset]=useState(false),[coachNewPassword,setCoachNewPassword]=useState(''),[adminLogin,setAdminLogin]=useState({email:'',password:''});const set=(k,v)=>setForm({...form,[k]:v});async function doAdminLogin(){setError('');if(busy)return;setBusy(true);try{const body=new URLSearchParams({username:adminLogin.email.trim().toLowerCase(),password:adminLogin.password});const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Credenciales inválidas');if(d.user?.role!=='admin')throw new Error('Este usuario no tiene perfil de administrador.');const session={token:d.access_token,user:d.user};localStorage.setItem('defe_admin',JSON.stringify(session));location.reload()}catch(e){setError(e.message||'No pudimos ingresar.')}finally{setBusy(false)}}async function doCoachLogin(){setError('');setBusy(true);try{const body=new URLSearchParams({username:coachLogin.identifier.trim().toLowerCase(),password:coachLogin.password});const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),d=await r.json();if(!r.ok)throw new Error(d.detail||'Credenciales inválidas');if(d.user?.role!=='profe')throw new Error('Este usuario no tiene perfil de profesor.');const pr=await fetch('/api/profe/me',{headers:{Authorization:'Bearer '+d.access_token}}),pd=await pr.json();if(!pr.ok)throw new Error(pd.detail||'No se pudieron cargar las categorías asignadas.');localStorage.setItem('defe_coach',JSON.stringify({token:d.access_token,user:pd,categories:pd.categories||[]}));location.reload()}catch(e){setError(e.message)}finally{setBusy(false)}}async function resetPassword(){setError('');if(busy)return;setBusy(true);try{const r=await fetch('/api/reset-family-password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({identifier:login.identifier,password:newPassword})}),d=await r.json();if(!r.ok)throw new Error(d.error);setLogin({...login,password:newPassword});setReset(false);setNewPassword('');setError('Contraseña actualizada. Ya podés ingresar.')}catch(e){setError(e.message)}finally{setBusy(false)}}async function doLogin(){setError('');if(busy)return;setBusy(true);try{const body=new URLSearchParams({username:login.identifier.trim().toLowerCase(),password:login.password});const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body}),d=await r.json();if(!r.ok)throw new Error(d.detail||'No pudimos ingresar.');const token=d.access_token;const mr=await fetch('/api/me',{headers:{Authorization:'Bearer '+token}}),me=await mr.json();if(!mr.ok)throw new Error(me.detail||'No pudimos cargar tu cuenta.');const fr=await fetch('/api/availability/family/setup',{headers:{Authorization:'Bearer '+token}}),fd=await fr.json();if(!fr.ok)throw new Error(fd.detail||'No pudimos cargar tu familia.');const family={full_name:[me.first_name,me.last_name].filter(Boolean).join(' ')||me.email,email:me.email,phone:me.phone};const players=(fd.linked||[]).map(p=>({id:p.person_id,full_name:p.name,category:p.teams?.[0]?.category||'',birth_date:p.birth_date||''}));const session={family,players,token};localStorage.setItem('defe_token',token);localStorage.setItem('defe_family',JSON.stringify(session));done(session)}catch(e){setError(e.message)}finally{setBusy(false)}}async function submit(){setError('');setBusy(true);try{const full=form.fullName.trim().split(/\s+/);if(full.length<2)throw new Error('Completá nombre y apellido.');if(!form.email.trim())throw new Error('Ingresá un email.');if((form.password||'').length<8)throw new Error('La contraseña debe tener al menos 8 caracteres.');const first=full.shift(),last=full.join(' ');const r=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:form.email.trim().toLowerCase(),password:form.password,first_name:first,last_name:last,phone:form.phone})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'No pudimos crear la cuenta.');const token=d.access_token;const all=[...children,{playerName:form.playerName,birthDate:form.birthDate,category:form.category}].filter(x=>x.playerName&&x.category);if(!all.length)throw new Error('Agregá al menos un jugador.');const players=[];for(const child of all){const n=child.playerName.trim().split(/\s+/);if(n.length<2)throw new Error('Completá nombre y apellido del jugador.');const cf=n.shift(),cl=n.join(' ');const cr=await fetch('/api/availability/family/children',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+token},body:JSON.stringify({first_name:cf,last_name:cl,competition:'FEFI',category:child.category,birth_date:child.birthDate||null})}),cd=await cr.json();if(!cr.ok)throw new Error(cd.detail||('No pudimos agregar a '+child.playerName));if(cd.child)players.push({id:cd.child.person_id,full_name:cd.child.name,category:cd.child.teams?.[0]?.category||child.category,birth_date:child.birthDate||''})}const family={full_name:form.fullName.trim(),email:form.email.trim().toLowerCase(),phone:form.phone};const session={family,players,token};localStorage.setItem('defe_token',token);localStorage.setItem('defe_family',JSON.stringify(session));done(session)}catch(e){setError(e.message)}finally{setBusy(false)}}if(!mode)return <main className="welcome cleanWelcome"><div className="greenStroke topStroke"></div><div className="welcomeCenter"><img src={LOGO} alt="Escudo DEFE" className="welcomeLogo"/><div className="welcomeTitle">Mi DEFE</div><div className="welcomeSub"><i></i>BABY FÚTBOL<i></i></div><div className="siempreDefe">SIEMPRE DEFE</div><div className="cleanActions"><button className="loginHero" onClick={()=>setMode('login')}><span>●</span><strong>Ingresar</strong><b>›</b></button><button className="registerHero" onClick={()=>setMode('register')}><span>●+</span><strong>Crear cuenta</strong><b>›</b></button><InstallButton/></div></div><button className="adminEntry" aria-label="Administración" onClick={()=>setMode("adminlogin")}>DEFE</button><div className="greenStroke bottomStroke"></div></main>;if(mode==='adminlogin')return <main><header><div className="brand"><img className="clubLogo" src={LOGO}/><div><b>GESTIÓN DEFE</b><small>ADMINISTRACIÓN</small></div></div></header><article className="register"><small>ACCESO RESTRINGIDO</small><h1>Administración</h1><section><label>Usuario<input value={adminLogin.email} onChange={e=>setAdminLogin({...adminLogin,email:e.target.value})} placeholder="Usuario"/></label><label>Contraseña<input type="password" value={adminLogin.password} onChange={e=>setAdminLogin({...adminLogin,password:e.target.value})} placeholder="••••••••"/></label>{error&&<p className="formError">{error}</p>}<button className="primary wide" disabled={busy} onClick={doAdminLogin}>{busy?'Ingresando…':'Ingresar'}</button><button className="backBtn" onClick={()=>setMode(null)}>← Volver</button></section></article></main>;if(mode==='login')return <main><header><div className="brand"><img className="clubLogo" src={LOGO}/><div><b>MI DEFE</b><small>BABY FÚTBOL · FEFI</small></div></div></header><article className="register"><small>YA ESTOY REGISTRADO</small><h1>Ingresar</h1><p className="authIntro">Elegí cómo ingresás a Mi DEFE.</p><div className="roleCards loginRoles"><button className={loginType==='familia'?'active':''} onClick={()=>{setLoginType('familia');setError('');setReset(false);setCoachReset(false)}}><Users/><b>Familia</b><small>Mis hijos y su actividad</small></button><button className={loginType==='profe'?'active':''} onClick={()=>{setLoginType('profe');setError('');setReset(false);setCoachReset(false)}}><Trophy/><b>Profesor</b><small>Plantel y convocatorias</small></button></div><section><small>{loginType==='familia'?'ACCESO FAMILIA':'ACCESO PROFESOR'}</small><h3>{loginType==='familia'?'Ingresar':'Ingresar como profesor'}</h3>{loginType==='familia'?<><label>Celular o email<input value={login.identifier} onChange={e=>setLogin({...login,identifier:e.target.value})} placeholder="Tu celular o email"/></label><label>Contraseña<input type="password" value={login.password} onChange={e=>setLogin({...login,password:e.target.value})} placeholder="••••••••"/></label>{error&&<p className="formError">{error}</p>}{!reset&&<><button className="primary wide continue" disabled={busy} onClick={doLogin}>{busy?"Ingresando…":"Ingresar"}</button><button type="button" className="forgot" onClick={()=>{setReset(true);setError('')}}>Olvidé mi contraseña</button></>}{reset&&<div className="resetBox"><p>Ingresá el celular o email de tu cuenta y elegí una nueva contraseña.</p><label>Nueva contraseña<input type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="Mínimo 6 caracteres"/></label><button type="button" className="primary wide" disabled={busy} onClick={resetPassword}>{busy?'Guardando…':'Cambiar contraseña'}</button><button type="button" className="forgot" disabled={busy} onClick={()=>{setReset(false);setError('')}}>Cancelar</button></div>}</>:<><label>Celular o email<input value={coachLogin.identifier} onChange={e=>setCoachLogin({...coachLogin,identifier:e.target.value})} placeholder="Celular o email"/></label><label>Contraseña<input type="password" value={coachLogin.password} onChange={e=>setCoachLogin({...coachLogin,password:e.target.value})} placeholder="••••••••"/></label>{error&&<p className="formError">{error}</p>}<button className="primary wide" disabled={busy} onClick={doCoachLogin}>{busy?'Ingresando…':'Ingresar como profesor'}</button></>}<div className="loginRoleLinks"><button type="button" className="adminAccessBtn" onClick={()=>{setError('');setMode('adminlogin')}}><span className="adminGear">⚙</span><span>Administrador</span><b>›</b></button></div><button className="backBtn" onClick={()=>setMode(null)}>← Volver</button></section></article></main>;return <main><header><div className="brand"><img className="clubLogo" src={LOGO}/><div><b>MI DEFE</b><small>BABY FÚTBOL · FEFI</small></div></div></header><article className="register"><small>CREAR CUENTA</small><h1>Sumate a Mi DEFE</h1><p className="authIntro">Creá tu cuenta y empezá a vivir el club más cerca.</p><section><label>Nombre y apellido<input value={form.fullName} onChange={e=>set('fullName',e.target.value)} placeholder="Nombre completo"/></label><label>Celular<input value={form.phone} onChange={e=>set('phone',e.target.value)} placeholder="11 1234 5678"/></label><label>Email<input type="email" value={form.email} onChange={e=>set('email',e.target.value)} placeholder="tu@email.com"/></label><label>Contraseña<input type="password" value={form.password} onChange={e=>set('password',e.target.value)} placeholder="Elegí una contraseña"/></label><hr/><label>Nombre del jugador<input value={form.playerName} onChange={e=>set('playerName',e.target.value)} placeholder="Nombre y apellido"/></label><label>Fecha de nacimiento<input type="date" value={form.birthDate} onChange={e=>set('birthDate',e.target.value)}/></label><label>Plantel<select className="wide" value={form.category} onChange={e=>set('category',e.target.value)}>{FEFI_CATEGORIES.map(y=><option key={y} value={y}>{y}</option>)}</select></label>{error&&<p className="formError">{error}</p>}<button type="button" className="addChild" onClick={()=>{if(form.playerName&&form.birthDate){setChildren([...children,{playerName:form.playerName,birthDate:form.birthDate,category:form.category}]);setForm({...form,playerName:'',birthDate:'',category:'2013'})}else setError('Completá nombre y fecha de nacimiento antes de agregar otro hijo.')}}>+ Agregar otro hijo</button>{children.length>0&&<div className="childrenAdded"><small>HIJOS AGREGADOS</small>{children.map((h,i)=><div key={i}><b>{h.playerName}</b><span>{h.category}</span><button onClick={()=>setChildren(children.filter((_,x)=>x!==i))}>×</button></div>)}</div>}<button className="primary wide continue" disabled={busy} onClick={submit}>{busy?'Creando cuenta…':'Crear mi cuenta'}</button></section><button className="backBtn" onClick={()=>setMode(null)}>← Volver</button></article></main>}
function App(){const admin=(()=>{try{return JSON.parse(localStorage.getItem('defe_admin'))}catch{return null}})();if(admin?.token&&admin?.user?.role==='admin')return <AdminHome session={admin}/>;const coach=(()=>{try{return JSON.parse(localStorage.getItem('defe_coach'))}catch{return null}})();if(coach?.token&&coach?.user?.role==='profe')return <CoachHome session={coach}/>;const saved=()=>{try{return JSON.parse(localStorage.getItem('defe_family'))||null}catch{return null}};const[session,setSession]=useState(saved);async function refresh(){const token=localStorage.getItem('defe_token');if(!token)return;const [mr,fr]=await Promise.all([fetch('/api/me',{headers:{Authorization:'Bearer '+token}}),fetch('/api/availability/family/setup',{headers:{Authorization:'Bearer '+token}})]);if(!mr.ok||!fr.ok)throw new Error();const me=await mr.json(),fd=await fr.json();const next={family:{full_name:[me.first_name,me.last_name].filter(Boolean).join(' ')||me.email,email:me.email,phone:me.phone},players:(fd.linked||[]).map(p=>({id:p.person_id,full_name:p.name,category:p.teams?.[0]?.category||'',birth_date:p.birth_date||''})),token};localStorage.setItem('defe_family',JSON.stringify(next));setSession(next)}useEffect(()=>{refresh().catch(()=>{localStorage.removeItem('defe_token');localStorage.removeItem('defe_family');setSession(null)})},[]);return session?.family?<FamilyHome family={session.family} players={session.players||[]} refresh={refresh}/>:<Register done={setSession}/>}createRoot(document.getElementById('root')).render(<App/>);